-- ------------------------------------------------------------
-- 016: poligonos de los lotes de Ciudadela San Lucas sobre el plano
-- ------------------------------------------------------------
-- Contorno de 201 lotes (LADRILLERA H, I, J, K, N, O, P y Q) calculado
-- a partir de las lineas del plano catastral (COMPLETA.pdf), con las mismas
-- coordenadas que la app: [[x, y], ...] normalizadas a 0..1 sobre el ancho y
-- alto de la imagen del plano. Los poligonos de H1-H12 ya dibujados a mano
-- coinciden con estos (diferencia media < 0.001), asi que se reescriben igual.
--
-- NO crea columnas: solo actualiza lotes.poligono (ya existe), buscando cada
-- lote por su codigo_catastral (ya cargado; unico por lote).
-- No tocan: LADRILLERA L1/L2/L3 y M (sin codigo catastral en el plano), ni el
-- estado, precio u otros campos. Idempotente.
--
-- Ejecutar en el SQL Editor de Supabase (igual que las demas migraciones).
-- ------------------------------------------------------------

UPDATE public.lotes AS l
SET poligono = v.poligono::jsonb
